#!/usr/bin/env bash
# Public server certificate only. The private key remains on the ZOJ server.
# Run on pve01; optional arguments select node numbers.
set -euo pipefail
script=$(mktemp)
trap 'rm -f "$script"' EXIT
curl -fSL --connect-timeout 10 --max-time 60 \
  https://raw.githubusercontent.com/ZERONE-Online-Judge/judge-agent-v1/b032b6633f416ca4620f22940e95f7965b71dfc0/deploy/use-internal-api.sh \
  -o "$script"
printf '%s  %s\n' 'e5bb67a19459515f11e62a5f363698023356b87efb8976bcd2f42d1c07bd29fa' "$script" | sha256sum -c -
export ZOJ_INTERNAL_API_BASE_URL=https://10.10.10.110:6443/api
export ZOJ_INTERNAL_TLS_CERT_B64=''
bash "$script" "$@"
